Gerard Goossen wrote:
> kurila 1.3 released
> 
> 
> Perl Kurila 1.3 tries to reduce some ambiguities in Perl code, and to
> simplify the perl internals. Some uncommon and error prone options
> have been removed.
> 
> Highlights:
> + Dereference of a string (aka. soft or symbolic references) will
>   always give an error, even when not "use strict 'refs'"

Without symbolic refs how does one make a named closure?  All those fancy
accessor generation modules out there rely on soft references like so.

	sub make_accessor {
		my($class, $name) = @_;

		my $code = sub {
			my $self = shift;
			if( @_ ) {
				$self->$name(@_):
			}
			return $self->$name();
		};

		no strict 'refs';
		*{$class . '::' . $name} = $code;
	}


PS  I'm sorry that this post isn't one bitching about Perl 6 or 5.004
compatibility or project resources or Python 3000.  It's a question about
kurila.  Sorry to go off topic. :P


-- 
I have a date with some giant cartoon robots and booze.

# New Ticket Created by  Andy Dougherty 
# Please include the string:  [perl #46111]
# in the subject line of all future correspondence about this issue. 
# 


The following patch adds tests for commands that print only to stderr to 
the IPC::Cmd test suite.

These tests currently fail for me under Solaris 8 with Sun's cc compiler. 
(And this failure ultimately shows up as a failure in Archive::Extract 
when it tries to parse the stderr output of bzip2 --version).


diff -ru perl-current/lib/IPC/Cmd/t/01_IPC-Cmd.t perl-andy/lib/IPC/Cmd/t/01_IPC-Cmd.t
--- perl-current/lib/IPC/Cmd/t/01_IPC-Cmd.t	Tue Nov 28 05:45:22 2006
+++ perl-andy/lib/IPC/Cmd/t/01_IPC-Cmd.t	Fri Oct  5 13:26:32 2007
@@ -35,7 +35,7 @@
     ok( !can_run('10283lkjfdalskfjaf'), q[Not found non-existant binary] );
 }

-### run tests
+### run tests that print only to stdout
 {   ### list of commands and regexes matching output ###
     my $map = [
         # command                                    # output regex
@@ -45,6 +45,7 @@
         [ [$^X,qw[-eprint+42 |], $^X, qw|-neprint|], qr/42/,            ],
     ];

+    diag( "Running tests that print only to stdout" ) if $Verbose;
     ### for each configuarion
     for my $pref ( @Prefs ) {
         diag( "Running config: IPC::Run: $pref->[0] IPC::Open3: $pref->[1]" )
@@ -108,6 +109,79 @@
     }
 }

+### run tests that print only to stderr
+{   ### list of commands and regexes matching output ###
+    my $map = [
+        # command                                    # output regex
+        [ "$^X -ewarn+42",                          qr/^42 /, ],
+        [ [$^X, '-ewarn+42'],                       qr/^42 /, ],
+    ];
+
+    diag( "Running tests that print only to stderr" ) if $Verbose;
+    ### for each configuarion
+    for my $pref ( @Prefs ) {
+        diag( "Running config: IPC::Run: $pref->[0] IPC::Open3: $pref->[1]" )
+            if $Verbose;
+
+        $IPC::Cmd::USE_IPC_RUN    = $IPC::Cmd::USE_IPC_RUN      = $pref->[0];
+        $IPC::Cmd::USE_IPC_OPEN3  = $IPC::Cmd::USE_IPC_OPEN3    = $pref->[1];
+
+        ### for each command
+        for my $aref ( @$map ) {
+            my $cmd                 = $aref->[0];
+            my $regex               = $aref->[1];
+
+            my $pp_cmd = ref $cmd ? "@$cmd" : "$cmd";
+            diag( "Running '$pp_cmd' as " . (ref $cmd ? "ARRAY" : "SCALAR") )
+                if $Verbose;
+
+            ### in scalar mode
+            {   diag( "Running stderr command in scalar mode" ) if $Verbose;
+                my $buffer;
+                my $ok = run( command => $cmd, buffer => \\$buffer );
+
+                ok( $ok,        "Ran stderr command succesfully in scalar mode." );
+
+                SKIP: {
+		    # No buffers are expected if neither IPC::Run nor IPC::Open3 is used.
+                    skip "No buffers available", 1
+                                unless $Class->can_capture_buffer;
+
+                    like( $buffer, $regex,
+                                "   Buffer filled properly from stderr" );
+                }
+            }
+
+            ### in list mode
+            {   diag( "Running stderr command in list mode" ) if $Verbose;
+                my @list = run( command => $cmd );
+                ok( $list[0],   "Ran stderr command successfully in list mode." );
+                ok( !$list[1],  "   No error code set" );
+
+                my $list_length = $Class->can_capture_buffer ? 5 : 2;
+                is( scalar(@list), $list_length,
+                                "   Output list has $list_length entries" );
+
+                SKIP: {
+		    # No buffers are expected if neither IPC::Run nor IPC::Open3 is used.
+                    skip "No buffers available", 6
+                                unless $Class->can_capture_buffer;
+
+                    ### the last 3 entries from the RV, are they array refs?
+                    isa_ok( $list[$_], 'ARRAY' ) for 2..4;
+
+                    like( "@{$list[2]}", $regex,
+                                "   Combined buffer holds output" );
+
+                    is( scalar( @{$list[3]} ), 0,
+                                    "   Stdout buffer empty" );
+                    like( "@{$list[4]}", qr/$regex/,
+                            "   Stderr buffer filled" );
+                }
+            }
+        }
+    }
+}

 ### test failures
 {   ### for each configuarion

-- 
    Andy Dougherty		uloqorhi@lafayette.edu

On 2007â€“10â€“05, at 16:43, H.Merijn Brand wrote:

> You made it too ugly imho
>
> -    print join(':', split(/ */, 'hi there'));
> +    print(join(':', split(/ */, 'hi there')), "\\n");
> *    print join(':', split(/ */, 'hi there'), "\\n");

But that produces slightly different output:

$ perl
print join(':', split(/ */, 'hi there'), "\\n");
h:i:t:h:e:r:e:
$ perl
print(join(':', split(/ */, 'hi there')), "\\n");
h:i:t:h:e:r:e

-- 
Dominic Dunlop

This

    #!/usr/bin/perl

    sub PVBM () { 'foo' }
    index "foo", PVBM;

    $x = PVBM;

    my $str = 'foo';
    my $pvlv = \\substr $str, 0, 1;

    $x = $pvlv;

    __END__

causes (the same) assertion failure in glob_assign_ref, which it should
never have got to in the first place. The patch below appears to fix it.

Ben

diff -ur perl-current/sv.c perl-current-pvbm/sv.c
--- perl-current/sv.c	Sat Oct  6 22:32:11 2007
+++ perl-current-pvbm/sv.c	Tue Oct 16 18:20:31 2007
@@ -3536,7 +3536,7 @@
 	}

 	if (dtype >= SVt_PV) {
-	    if (dtype == SVt_PVGV) {
+	    if (dtype == SVt_PVGV && isGV_with_GP(dstr)) {
 		glob_assign_ref(dstr, sstr);
 		return;
 	    }
diff -ur perl-current/t/op/lex_assign.t perl-current-pvbm/t/op/lex_assign.t
--- perl-current/t/op/lex_assign.t	Tue Jun 13 20:29:32 2006
+++ perl-current-pvbm/t/op/lex_assign.t	Tue Oct 16 18:41:09 2007
@@ -24,7 +24,7 @@

 @INPUT = ;
 @simple_input = grep /^\\s*\\w+\\s*\\$\\w+\\s*[#\\n]/, @INPUT;
-print "1..", (10 + @INPUT + @simple_input), "\\n";
+print "1..", (11 + @INPUT + @simple_input), "\\n";
 $ord = 0;

 sub wrn {"@_"}
@@ -170,6 +170,25 @@
     }
   }
 }
+
+$ord++;
+eval {
+    sub PVBM () { 'foo' }
+    index 'foo', PVBM;
+    my $x = PVBM;
+
+    my $str = 'foo';
+    my $pvlv = \\substr $str, 0, 1;
+    $x = $pvlv;
+
+    1;
+};
+if ($@) {
+    warn "# $@";
+    print 'not ';
+}
+print "ok $ord\\n";
+
 __END__
 ref $xref			# ref
 ref $cstr			# ref nonref
